/**
 * Policy Mappings
 * (sails.config.policies)
 *
 * Policies are simple functions that run before your actions. The mapping is
 * matched most-specific-first, so a `controller/action` key beats a
 * `controller/*` key, which beats the catch-all `'*'`.
 *
 * @docs https://sailsjs.com/docs/concepts/policies
 */

module.exports.policies = {

  // Nothing in this app is anonymous unless it is listed below.
  '*': 'isLoggedIn',

  // The sign-in / sign-up / forgotten-password screens.
  'entrance/*': true,

  // Portal users legitimately reach these -- the actions themselves work out
  // which records the caller is allowed to see.
  'account/*': 'isLoggedIn',
  'invoices/*': 'isLoggedIn',
  'patients/*': 'isLoggedIn',
  'lab-results/*': 'isLoggedIn',

  // Internal-only screens.
  'reports/*': ['isLoggedIn', 'isClinicStaff'],
  'staff/*': ['isLoggedIn', 'isClinicStaff'],
  'rota/*': ['isLoggedIn', 'isClinicStaff'],

  // Billing is staff-only.
  'billing/apply-credit-note': ['isLoggedIn', 'isClinicStaff']

};

